<script setup lang="ts">
const {matches,addEvent,addMatch}=useLeague();const selected=ref(matches.value[0].id);const type=ref<'goal'|'yellow'|'red'|'substitution'>('goal');const minute=ref(82);const team=ref('Madariaga');const player=ref('');const playerIn=ref('');const playerOut=ref('');const newHome=ref('');const newAway=ref('');
function save(){addEvent(selected.value,{minute:minute.value,type:type.value,team:team.value,player:player.value,playerIn:playerIn.value,playerOut:playerOut.value});player.value='';playerIn.value='';playerOut.value=''}
function create(){if(!newHome.value||!newAway.value)return;addMatch({date:'2026-10-18 16:30',home:newHome.value,away:newAway.value,homeScore:0,awayScore:0,status:'scheduled'});newHome.value='';newAway.value=''}
</script>
<template><div><div class="topbar"><span>liga.futbol.app · administración</span><b>Panel de liga</b></div><nav class="nav"><div class="brand">LIGA LIBREÑA<br>ADMIN</div><div class="navlinks"><NuxtLink to="/">Vista pública</NuxtLink><NuxtLink class="active" to="/admin">Administrar</NuxtLink></div></nav><main class="shell"><div class="page-title"><div><h1>Panel de administración</h1><p class="muted">Organizá la liga, torneos, partidos y actas.</p></div><span class="badge">Datos locales de demo</span></div><div class="actionbar"><button class="btn">Liga Libreña</button><button class="btn secondary">Torneo Oficial 2026</button><button class="btn secondary">Fecha 7</button></div><div class="grid"><section class="panel"><div class="panel-head"><h2>Cargar evento</h2><span class="muted">Partido seleccionado</span></div><div class="panel-body"><div class="field"><label>Partido</label><select v-model="selected"><option v-for="m in matches" :value="m.id">{{m.home}} vs {{m.away}}</option></select></div><div class="grid" style="grid-template-columns:1fr 1fr;gap:10px"><div class="field"><label>Minuto</label><input v-model="minute" type="number"></div><div class="field"><label>Equipo</label><select v-model="team"><option>Madariaga</option><option>Puente Seco</option></select></div></div><div class="field"><label>Tipo de evento</label><select v-model="type"><option value="goal">⚽ Gol</option><option value="yellow">🟨 Tarjeta amarilla</option><option value="red">🟥 Tarjeta roja</option><option value="substitution">🔁 Cambio</option></select></div><div v-if="type==='substitution'" class="grid" style="grid-template-columns:1fr 1fr;gap:10px"><div class="field"><label>Jugador que sale</label><input v-model="playerOut" placeholder="Rodrigo Acosta"></div><div class="field"><label>Jugador que entra</label><input v-model="playerIn" placeholder="Martín Sosa"></div></div><div v-else class="field"><label>Jugador (opcional)</label><input v-model="player" placeholder="Martín Sosa"></div><button class="btn" @click="save">Registrar evento</button></div></section><section class="panel"><div class="panel-head"><h2>Crear partido</h2><span class="muted">Fixture</span></div><div class="panel-body"><div class="field"><label>Local</label><input v-model="newHome" placeholder="Ej. Mitre"></div><div class="field"><label>Visitante</label><input v-model="newAway" placeholder="Ej. Barraca"></div><button class="btn" @click="create">Agregar al fixture</button><div class="list" style="margin-top:20px"><div v-for="m in matches" class="item"><span><b>{{m.home}} vs {{m.away}}</b><small class="muted">{{m.date}}</small></span><span class="badge">{{m.status}}</span></div></div></div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Últimos eventos</h2><span class="muted">Se reflejan en la vista pública</span></div><div class="panel-body"><div v-for="event in matches.find(m=>m.id===selected)?.events" :key="event.id" class="item"><span><b>{{event.type}} · {{event.team}}</b><small class="muted">{{event.minute}}' · {{event.player||`${event.playerOut} → ${event.playerIn}`}}</small></span></div></div></section></main></div></template>
